CREATE POLICY "exercise images own select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'exercise-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "exercise images own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'exercise-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "exercise images own update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'exercise-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "exercise images own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'exercise-images' AND (storage.foldername(name))[1] = auth.uid()::text);